import {SCENARIOS,BUSES,ARRAYS,BATTERIES,RADIOS,INSTRUMENTS,ORBITS,LAUNCHERS,DIFFICULTIES,TEAM_ROLES,defaultPlan,sanitizePlan,evaluatePlan,fieldOwner,createSimulation,stepSimulation,missionReport,expeditionModifiers} from './engineering.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const options=(items,value,label=x=>x.name)=>items.map(x=>`<option value="${x.id}" ${x.id===value?'selected':''}>${esc(label(x))}</option>`).join('');
const STORE='tminus-designs-v1',DRAFT='tminus-draft-v1';
export function initPlanner(api,settings={}){let plan=defaultPlan(),approvals=[false,false,false,false],activeRole=0,revision=1,tab='design',simulation=null,running=false,policy='balanced',speed=3,tick=0,inspect=false,opened=false,notice='',activity=[],saved=[],priorPaused=false,report=null;const root=document.createElement('section');root.id='mission-control';root.hidden=true;root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','Mission control');document.body.append(root);
try{const parsed=JSON.parse(localStorage.getItem(STORE)||'[]');saved=Array.isArray(parsed)?parsed.filter(x=>x&&typeof x==='object'&&x.plan&&x.report&&typeof x.report.score==='number').slice(0,8):[];const draft=JSON.parse(localStorage.getItem(DRAFT)||'null');if(draft)plan=sanitizePlan(draft);}catch{}
try{const hash=location.hash;if(hash.startsWith('#design=')){const decoded=decodeURIComponent(escape(atob(hash.slice(8).replace(/-/g,'+').replace(/_/g,'/'))));plan=sanitizePlan(JSON.parse(decoded));notice='Shared design loaded. Crew approvals start fresh.';}}catch{notice='The shared design could not be read. A safe default design is loaded.';}
function flash(text){notice=text;const node=root.querySelector('.mc-notice');if(node)node.textContent=text;}
function storeDraft(){try{localStorage.setItem(DRAFT,JSON.stringify(plan));}catch{flash('Browser storage is unavailable. Export your design to keep a copy.');}}
function owner(field){return fieldOwner(field,plan.teamSize);}function editable(field){return plan.teamSize===1||owner(field)===activeRole;}
function approved(){return plan.teamSize===1||approvals.slice(0,plan.teamSize).every(Boolean);}
function change(field,value){if(!editable(field)){flash('This setting belongs to '+TEAM_ROLES[owner(field)].name+'. Select that participant first.');return;}const before=JSON.stringify(plan);if(field==='scenario'){const team=plan.teamSize,diff=plan.difficulty;plan={...defaultPlan(value),teamSize:team,difficulty:diff};}else plan=sanitizePlan({...plan,[field]:value});if(JSON.stringify(plan)===before)return;revision++;approvals=[false,false,false,false];activeRole=Math.min(activeRole,plan.teamSize-1);simulation=null;report=null;running=false;activity.unshift(`${TEAM_ROLES[activeRole].name} updated ${field}. All reviews reset.`);activity=activity.slice(0,6);notice='Design revision '+revision+' · Resource estimates updated.';storeDraft();api.previewDesign?.(plan);render();}
function open(){if(opened)return;priorPaused=api.mission.paused;api.setPlanning(true);opened=true;root.hidden=false;document.body.classList.add('planning');api.previewDesign?.(plan);render();root.querySelector('.mc-nav button')?.focus();}
function close(){opened=false;running=false;inspect=false;api.inspectDesign?.(false);root.hidden=true;document.body.classList.remove('planning');api.setPlanning(false,priorPaused);document.querySelector('#open-mission-control')?.focus();}
function startExpedition(){const e=evaluatePlan(plan);if(!e.valid){flash('Resolve the red preflight checks before launching. You can simulate an invalid design to see why it fails.');return;}if(!approved()){flash('Every participant must review this design revision before launch.');return;}running=false;api.startConfiguredExpedition(plan,expeditionModifiers(plan));priorPaused=false;close();}
function saveDesign(){const current=report||simulation&&missionReport(simulation,approvals);if(!current){flash('Complete a simulation before saving a comparison.');return;}const item={id:Date.now(),name:SCENARIOS.find(s=>s.id===plan.scenario).subtitle,plan:sanitizePlan(plan),report:current,revision};saved.unshift(item);saved=saved.slice(0,8);try{localStorage.setItem(STORE,JSON.stringify(saved));flash('Design and report saved to this browser.');}catch{flash('Browser storage is full or unavailable. Use Export design.');}render();}
function download(value,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function share(){const raw=unescape(encodeURIComponent(JSON.stringify(plan))),encoded=btoa(raw).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const url=location.origin+location.pathname+'#design='+encoded;try{await navigator.clipboard.writeText(url);flash('Design link copied. It shares configuration; each browser keeps its own simulation and approvals.');}catch{flash('Copy the design link from the box below.');const box=root.querySelector('#mc-share-link');box.hidden=false;box.value=url;box.focus();box.select();}}
function selectField(title,field,items,note,label){const own=owner(field);return `<label class="mc-field"><span>${title}${plan.teamSize>1?`<small>${TEAM_ROLES[own].name}</small>`:''}</span><select data-field="${field}" ${editable(field)?'':'disabled'}>${options(items,plan[field],label)}</select><small>${esc(note)}</small></label>`;}
function resourceCard(e){const rows=[['Launch mass',e.mass,e.capacity,'kg',0,e.capacity>0&&e.mass<=e.capacity,'Structure + systems + payload + propellant'],['Budget',e.cost,e.budget,'M',1,e.cost<=e.budget||plan.difficulty==='sandbox','Spacecraft development + launch + propellant'],['Average power',e.load,e.generated,'W',0,e.powerMargin>=0,'Demand versus sunlight-adjusted generation'],['Eclipse battery',e.eclipseRequired,e.battery.capacity,'Wh',0,e.eclipseRequired<=e.battery.capacity,'Energy needed during the dark portion of one orbit'],['Daily data',e.dataDaily,e.downlinkDaily,'GB',2,e.dataDaily<=e.downlinkDaily,'Data collected versus data that can reach Earth'],['Propellant',e.fuelRequired,plan.fuel,'kg',1,e.fuelRequired<=plan.fuel,'Injection + planned station keeping, before surprises']];return `<aside class="mc-resources"><div class="mc-panel mc-budget-panel"><div class="mc-kicker">ENGINEERING LEDGER <span>LIVE</span></div><h3>Every choice<br>has a cost.</h3>${rows.map(([name,v,max,unit,d,ok,tip])=>`<div class="mc-resource ${ok?'':'over'}" title="${tip}"><div><span>${name}</span><strong>${fmt(v,d)} <small>/ ${fmt(max,d)} ${unit}</small></strong></div><div class="mc-track"><i style="width:${Math.min(100,max>0?v/max*100:100)}%"></i></div></div>`).join('')}<p class="mc-fine">${fmt(e.scienceDaily)} potential science/day · ${fmt(e.target)} points needed. Science earns points after downlink.</p><button data-start-simulation class="mc-primary mc-sidebar-run" ${running?'disabled':''}>SIMULATE DESIGN ↗</button></div><div class="mc-panel mc-preflight"><div class="mc-kicker">PREFLIGHT <span class="${e.valid?'good':'bad'}">${e.errors.length?e.errors.length+' BLOCKER'+(e.errors.length===1?'':'S'):'LAUNCH COMPATIBLE'}</span></div>${e.checks.length?e.checks.map(c=>`<details class="mc-check ${c.level}"><summary><b>${c.level==='error'?'!':c.level==='warn'?'△':'i'}</b>${esc(c.title)}</summary><p>${esc(c.why)}</p><p class="mc-tip">${esc(c.fix)}</p></details>`).join(''):'<p class="mc-all-clear">✓ Mass, budget, fuel, power and downlink are within their planned limits.</p>'}<p class="mc-fine">Simulation tests margins under disruptions.</p></div></aside>`;}
function teamStrip(){return `<section class="mc-team mc-panel"><div><div class="mc-kicker">${plan.teamSize===1?'SOLO MISSION':'SHARED-DEVICE TEAM PLANNING'}</div><p>${plan.teamSize===1?'You control every engineering decision.':'Pass the device between participants. Select your role to edit its systems.'}</p></div><div class="mc-team-controls"><label>Participants <select data-field="teamSize" ${editable('teamSize')?'':'disabled'}>${[1,2,3,4].map(n=>`<option value="${n}" ${plan.teamSize===n?'selected':''}>${n===1?'1 · Solo':n+' · Team'}</option>`).join('')}</select></label>${plan.teamSize>1?`<div class="mc-role-tabs">${TEAM_ROLES.slice(0,plan.teamSize).map((r,i)=>`<button data-participant="${i}" class="${i===activeRole?'selected':''}" style="--role:${r.color}" title="${r.responsibility}"><span>${r.icon}</span>${r.name}<b>${approvals[i]?'✓':''}</b></button>`).join('')}</div><button class="mc-button mc-review" id="mc-approve" ${approvals[activeRole]?'disabled':''}>${approvals[activeRole]?'REVIEWED ✓':'REVIEW AS '+TEAM_ROLES[activeRole].name.toUpperCase()}</button>`:''}</div>${plan.teamSize>1?`<small class="mc-team-status">${approvals.slice(0,plan.teamSize).filter(Boolean).length}/${plan.teamSize} approvals · Revision ${revision} · ${TEAM_ROLES[activeRole].responsibility}. Changes reset all approvals. Unassigned responsibilities belong to the mission lead.</small>${activity.length?`<div class="mc-activity">${activity.slice(0,4).map(line=>`<p>${esc(line)}</p>`).join('')}</div>`:''}`:''}</section>`;}
function missionSidebar(e){return `<aside class="mc-scenarios"><div class="mc-kicker">CHOOSE YOUR OBJECTIVE</div>${SCENARIOS.map((s,i)=>`<button class="mc-scenario ${s.id===plan.scenario?'selected':''}" data-scenario="${s.id}" ${editable('scenario')?'':'disabled'} style="--mission-color:${s.color}"><span class="mc-planet planet-${i}"></span><small>0${i+1} / ${s.body.toUpperCase()}</small><b>${s.name}</b><span>${s.subtitle}</span></button>`).join('')}<div class="mc-side-note"><span>◎</span><p>Start with the question.<br>Build only what your mission needs.</p></div><button id="mc-tutorial" class="mc-text-button">HOW THE MODEL WORKS ↗</button></aside>`;}
function designView(e){const bus=e.bus,array=e.array,battery=e.battery,radio=e.radio;return `<div class="mc-design-grid">${missionSidebar(e)}<div class="mc-design-content"><div class="mc-hero"><div class="mc-kicker">MISSION ${SCENARIOS.findIndex(s=>s.id===plan.scenario)+1} / ${e.scenario.body.toUpperCase()} EXPLORATION</div><h1>${esc(e.scenario.name)}<span>.</span></h1><p>${esc(e.scenario.description)}</p></div><section class="mc-panel"><div class="mc-section-title"><span>01</span><div><h2>Set the mission.</h2><p>Define success before choosing hardware.</p></div></div><div class="mc-fields">${selectField('Difficulty','difficulty',Object.entries(DIFFICULTIES).map(([id,v])=>({id,name:v.name})),'Cadet adds budget margin. Expert tightens it. Sandbox removes only the budget constraint.')}${selectField('Operating lifetime','days',[...new Set([30,60,90,120,180,plan.days])].sort((a,b)=>a-b).map(n=>({id:n,name:n+' days'})),'Longer operations collect more science and consume more propellant.',x=>x.name)}<label class="mc-field"><span>Event seed <small>Repeatable tests</small></span><input type="number" min="1" max="9999" data-field="seed" value="${plan.seed}" ${editable('seed')?'':'disabled'}><small>The same seed repeats the disruption schedule for fair design comparisons.</small></label></div><div class="mc-goal"><span>◈</span><div><b>${fmt(e.target)} SCIENCE POINTS</b><p>Deliver useful observations to Earth within ${plan.days} days. Data still aboard the spacecraft does not count.</p></div></div></section><section class="mc-panel"><div class="mc-section-title"><span>02</span><div><h2>Engineer the spacecraft.</h2><p>Keep the lights on. Leave room for the unexpected.</p></div><button id="mc-inspect" class="mc-button small">INSPECT IN 3D ↗</button></div><div class="mc-fields">${selectField('Structure & onboard systems','bus',BUSES,bus.note,x=>x.name+' · '+x.mass+' kg')}${selectField('Solar arrays','array',ARRAYS,array.note,x=>x.name+' · '+x.power+' W')}${selectField('Battery reserve','battery',BATTERIES,battery.note)}${selectField('Communications','radio',RADIOS,radio.note,x=>x.name+' · '+x.rate+' Mbps')}<label class="mc-field"><span>Propellant <small>${fmt(plan.fuel)} kg</small></span><input type="range" min="10" max="250" step="5" value="${plan.fuel}" data-field="fuel" ${editable('fuel')?'':'disabled'}><small>More propellant extends operations and cushions surprises, but every kilogram must be launched.</small></label><div class="mc-system-note"><b>${e.bus.storage} GB</b><span>ONBOARD STORAGE</span><small>Part of the ${esc(bus.name)}. Undelivered observations fill this buffer.</small></div></div></section><section class="mc-panel"><div class="mc-section-title"><span>03</span><div><h2>Choose what to discover.</h2><p>More instruments increase science, mass, power, cost and data.</p></div></div><div class="mc-payloads">${INSTRUMENTS.map(i=>{const selected=plan.payload.includes(i.id);const affinity=e.scenario.weights[i.id];return `<label class="mc-instrument ${selected?'selected':''}"><input type="checkbox" data-instrument="${i.id}" ${selected?'checked':''} ${editable('payload')?'':'disabled'}><div><div class="mc-instrument-title"><b>${i.name}</b><span class="${affinity>=1?'good':''}">${affinity>=1?'HIGH RELEVANCE':affinity>=.6?'SUPPORTING':'LOW RELEVANCE'}</span></div><p>${i.note}</p><div class="mc-specs"><span>${i.mass} kg</span><span>${i.power} W</span><span>${i.cost} M</span><span>${i.rate} Mbps</span><span>×${affinity} science fit</span></div></div></label>`;}).join('')}</div><label class="mc-field mc-hours"><span>Daily observation time <small>${plan.hours} hours/day</small></span><input type="range" min="1" max="16" step="1" data-field="hours" value="${plan.hours}" ${editable('hours')?'':'disabled'}><small>More observing time needs more average power and downlink capacity. During simulation, operations policies can adjust this schedule.</small></label></section><section class="mc-panel"><div class="mc-section-title"><span>04</span><div><h2>Find your way there.</h2><p>Orbit changes coverage, sunlight and contact with Earth.</p></div></div><div class="mc-fields">${selectField('Orbit','orbit',ORBITS,e.orbit.note,x=>x.name+' · '+x.altitude)}${selectField('Launch vehicle','launcher',LAUNCHERS,e.launcher.note,x=>x.name+' · '+x.cost+' M credits')}</div><div class="mc-orbit-strip"><svg viewBox="0 0 120 76" aria-label="Orbit illustration"><ellipse cx="60" cy="38" rx="53" ry="25" fill="none" stroke="#b7a0f360" stroke-dasharray="3 4" transform="rotate(-15 60 38)"/><circle cx="60" cy="38" r="17" fill="${e.scenario.color}33" stroke="${e.scenario.color}88"/><circle cx="101" cy="13" r="4" fill="#d5f591"/><path d="M95 13h-9M107 13h9" stroke="#d5f591" stroke-width="2"/></svg><div><b>${e.orbit.altitude}</b><small>ORBIT ALTITUDE</small></div><div><b>${fmt(e.orbit.sun*100)}%</b><small>SUNLIT TIME</small></div><div><b>${fmt(e.orbit.contact*100)}%</b><small>GROUND CONTACT</small></div><div><b>${fmt(e.orbit.coverage*100)}%</b><small>COVERAGE FACTOR</small></div></div></section>${teamStrip()}<div class="mc-design-actions"><button id="mc-run" class="mc-primary">SIMULATE THIS DESIGN <span>↗</span></button><button id="mc-flight" class="mc-button" ${e.valid&&approved()?'':'disabled'}>ENTER 3D EXPEDITION</button></div><p class="mc-fine">Simulation is available for every design, including failed preflight checks. Shared-device teams must approve the current revision before entering the 3D expedition. In 3D, spacecraft mass changes movement speed, power margin changes stamina recovery, downlink changes extraction speed, and fuel margin changes the flight reserve. Scientific mission success is evaluated in the simulator.</p></div>${resourceCard(e)}</div>`;}
function simulationView(e){const s=simulation;return `<div class="mc-sim-layout"><div><div class="mc-hero"><div class="mc-kicker">MISSION SIMULATION / ${esc(e.scenario.body.toUpperCase())}</div><h1>Test your margins<span>.</span></h1><p>Watch power, propellant and data over time. Change the operations policy when conditions change.</p></div>${!s?`<div class="mc-panel mc-empty"><span>◎</span><h2>Your flight plan is ready.</h2><p>The simulator advances one mission day at a time. It uses the chosen hardware, orbit and event seed.</p><button id="mc-run" class="mc-primary">START SIMULATION ↗</button></div>`:`<section class="mc-panel mc-simulation"><div class="mc-sim-top"><div><div class="mc-kicker">${s.done?s.aborted?'PREFLIGHT ABORT':'SIMULATION COMPLETE':running?'SIMULATION RUNNING':'SIMULATION PAUSED'}</div><h2>Day <b id="mc-sim-day">${s.day}</b><small> / ${plan.days}</small></h2></div><div class="mc-sim-controls"><button id="mc-play" class="mc-button" ${s.done?'disabled':''}>${running?'PAUSE':'RESUME'}</button><button id="mc-step" class="mc-button" ${s.done?'disabled':''}>+1 DAY</button><select id="mc-speed" aria-label="Simulation speed">${[1,3,10].map(n=>`<option value="${n}" ${speed===n?'selected':''}>${n} days/s</option>`).join('')}</select></div></div><div class="mc-progress"><i id="mc-sim-progress" style="width:${s.day/plan.days*100}%"></i></div><div id="mc-live-grid">${liveStats(s)}</div><div class="mc-chart-head"><span>SCIENCE DELIVERED</span><span>DATA BUFFER</span><span>BATTERY RESERVE</span></div><canvas id="mc-history" width="900" height="230" aria-label="Mission resource history"></canvas><div class="mc-chart-axis"><span>DAY 0</span><span>DAY ${plan.days}</span></div><div class="mc-policy-title"><div class="mc-kicker">OPERATIONS POLICY</div><small>Changes apply from the next simulated day.</small></div><div class="mc-policies">${[['balanced','Balanced','Planned observing and downlink'],['observe','Science first','30% more observation time'],['conserve','Conserve power','55% less observation time'],['downlink','Clear data backlog','65% more downlink; fewer observations']].map(([id,title,note])=>`<button data-policy="${id}" class="${policy===id?'selected':''}" ${s.done?'disabled':''}><b>${title}</b><small>${note}</small></button>`).join('')}</div><p class="mc-fine">Policy changes are recorded in the mission report. Transmitting science takes time and energy; stored data earns no score until it is sent.</p><div class="mc-event-feed" id="mc-event-feed">${eventFeed(s)}</div>${s.done?`<div class="mc-complete-actions"><button id="mc-show-report" class="mc-primary">OPEN MISSION REPORT ↗</button><button id="mc-run" class="mc-button">RUN AGAIN</button></div>`:''}</section>`}</div><aside>${resourceCard(e)}<div class="mc-panel mc-guide"><div class="mc-kicker">FLIGHT DIRECTOR NOTES</div><h3>Read the signals.</h3><p><b>Battery falling?</b> Conserve power while sunlight is disrupted.</p><p><b>Data buffer rising?</b> Prioritize downlink to protect valuable observations.</p><p><b>Science behind target?</b> Observe more, if energy and communications allow it.</p></div></aside></div>`;}
function liveStats(s){const e=s.evaluation;return `<div class="mc-live-grid"><div><span>SCIENCE / TARGET</span><b>${fmt(s.science)} <small>/ ${fmt(e.target)}</small></b></div><div><span>BATTERY</span><b>${fmt(s.energy)} <small>Wh</small></b></div><div><span>DATA BUFFER</span><b>${fmt(s.buffer,1)} <small>/ ${e.bus.storage} GB</small></b></div><div><span>PROPELLANT LEFT</span><b>${fmt(Math.max(0,s.fuel),1)} <small>kg</small></b></div><div><span>SPACECRAFT HEALTH</span><b>${fmt(s.health)}<small>%</small></b></div><div><span>DATA LOST</span><b class="${s.lostData>0?'bad':''}">${fmt(s.lostData,1)} <small>GB</small></b></div></div>`;}
function eventFeed(s){return s.aborted?`<div class="mc-event error"><b>DAY 0 / LAUNCH ABORTED</b><p>${esc(s.evaluation.errors.map(c=>c.title).join(' · '))}</p></div>`:s.log.length?s.log.slice().reverse().map(l=>`<div class="mc-event"><b>DAY ${l.day} / ${l.title.toUpperCase()}</b><p>${l.detail}</p></div>`).join(''):'<div class="mc-event"><b>FLIGHT DIRECTOR / ALL SYSTEMS NOMINAL</b><p>Event messages will appear here as the mission advances.</p></div>';}
function reportView(e){const r=report;return `<div class="mc-report-layout"><div><div class="mc-hero"><div class="mc-kicker">POST-MISSION ANALYSIS</div><h1>${r?r.success?'Mission accomplished':'A lesson in the margins':'Every result tells a story'}<span>.</span></h1><p>${r?'The outcome follows your engineering choices and operations decisions. Use these findings to revise and run again.':'Run a simulation to receive a scored report explaining what worked, what failed, and why.'}</p></div>${r?`<section class="mc-panel mc-report-result"><div class="mc-result-label ${r.success?'good':'bad'}">${r.aborted?'LAUNCH ABORTED':r.success?'OBJECTIVE ACHIEVED':'OBJECTIVE NOT ACHIEVED'}</div><div class="mc-score">${fmt(r.score)}<small>/ 1,000</small></div><div class="mc-score-parts">${Object.entries(r.categories).map(([key,v])=>`<div><span>${key.toUpperCase()}</span><b>${v}</b></div>`).join('')}</div><div class="mc-report-metrics"><div><b>${fmt(r.science)}</b><small>SCIENCE DELIVERED / ${fmt(r.target)}</small></div><div><b>${fmt(r.uptime*100)}%</b><small>EFFECTIVE UPTIME</small></div><div><b>${r.days} / ${r.plannedDays}</b><small>OPERATING DAYS</small></div></div></section><section class="mc-panel"><div class="mc-section-title"><span>◎</span><div><h2>Why it happened.</h2><p>Use the explanation to make the next design better.</p></div></div>${r.reasons.map(reason=>`<article class="mc-reason"><h3>${esc(reason.title)}</h3><p>${esc(reason.detail)}</p><div><span>TRY NEXT</span>${esc(reason.tip)}</div></article>`).join('')}</section><section class="mc-panel"><div class="mc-kicker">OPERATIONS RECORD / SEED ${plan.seed}</div><div class="mc-decision-list">${r.decisions.length?r.decisions.map(d=>`<span>Day ${d.day} → ${esc(d.policy)}</span>`).join(''):'No operations began.'}</div><p class="mc-fine">${esc(r.model)}</p></section><div class="mc-report-actions"><button id="mc-save" class="mc-primary">SAVE FOR COMPARISON ↗</button><button id="mc-export-report" class="mc-button">EXPORT REPORT</button><button data-tab="design" class="mc-button">REVISE DESIGN</button></div>`:`<div class="mc-panel mc-empty"><h2>Ready to test your spacecraft?</h2><button id="mc-run" class="mc-primary">SIMULATE CURRENT DESIGN ↗</button></div>`}</div>${resourceCard(e)}</div>`;}
function savedView(){return `<div class="mc-hero"><div class="mc-kicker">DESIGN ARCHIVE / THIS BROWSER</div><h1>Build. Compare. Improve<span>.</span></h1><p>Keep up to eight tested designs. Compare their engineering cost with the science that actually reached home.</p></div>${saved.length?`<section class="mc-panel mc-comparison"><table><thead><tr><th>MISSION</th><th>MASS</th><th>COST</th><th>SCIENCE</th><th>SCORE</th><th>RESULT</th><th>ACTIONS</th></tr></thead><tbody>${saved.map(s=>`<tr><td><b>${esc(s.name)}</b><small>${esc(s.plan.difficulty)} · ${s.plan.days} days · Seed ${s.plan.seed}</small></td><td>${fmt(s.report.mass)} kg</td><td>${fmt(s.report.cost,1)} M</td><td>${fmt(s.report.science)}</td><td>${fmt(s.report.score)}</td><td class="${s.report.success?'good':'bad'}">${s.report.success?'SUCCESS':'REVISE'}</td><td><button data-load="${s.id}" class="mc-text-button">LOAD</button><button data-remove="${s.id}" class="mc-text-button bad" aria-label="Remove saved design">×</button></td></tr>`).join('')}</tbody></table></section>`:'<section class="mc-panel mc-empty"><span>◈</span><h2>No saved designs yet.</h2><p>Complete a simulation and select Save for comparison in the report.</p><button data-tab="design" class="mc-primary">DESIGN A MISSION ↗</button></section>'}<div class="mc-archive-actions"><button id="mc-export-design" class="mc-button">EXPORT CURRENT DESIGN</button><label class="mc-button mc-file-button">IMPORT DESIGN<input id="mc-import" type="file" accept="application/json,.json"></label><button id="mc-share" class="mc-button">COPY DESIGN LINK</button></div><p class="mc-fine">Saved designs are local to this browser. Export a file or share a design link to move the configuration to another device. Team planning takes place on a shared device.</p>`;}
function render(){const scroll=root.querySelector('.mc-scroll')?.scrollTop||0,e=evaluatePlan(plan);root.classList.toggle('inspecting',inspect);root.innerHTML=`<div class="mc-header"><div class="mc-brand">T<span>−</span>MINUS<small>MISSION CONTROL</small></div><nav class="mc-nav" aria-label="Mission control sections">${[['design','01','DESIGN'],['simulate','02','SIMULATE'],['report','03','ANALYZE'],['saved','◈','COMPARE']].map(([id,num,name])=>`<button data-tab="${id}" class="${tab===id?'selected':''}" ${running&&tab!==id?'disabled':''}><span>${num}</span>${name}</button>`).join('')}</nav><button id="mc-close" class="mc-button small">${api.mission.ended?'CLOSE':'RETURN TO GAME'} ×</button></div><div class="mc-notice" role="status">${esc(notice||'Design a mission, test its resources, then fly your spacecraft.')}</div><input id="mc-share-link" class="mc-share-link" aria-label="Shareable design URL" readonly hidden><div class="mc-scroll">${tab==='design'?designView(e):tab==='simulate'?simulationView(e):tab==='report'?reportView(e):savedView()}<footer class="mc-footer"><span>T-MINUS / ENGINEERING THROUGH EXPLORATION</span><span>EDUCATIONAL MODEL · EARTH / MOON / MARS</span></footer></div><div class="mc-inspect-toolbar mc-panel"><div><span class="mc-kicker">SPACECRAFT INSPECTION</span><b>${e.array.name} · ${e.payload.length} instruments · ${fmt(e.mass)} kg</b><p>The solar wings and payload modules reflect your selected design.</p></div><button id="mc-end-inspect" class="mc-primary">RETURN TO DESIGN ↗</button></div>`;
root.querySelector('.mc-scroll').scrollTop=scroll;bind();if(tab==='simulate'&&simulation)drawHistory();}
function beginSimulation(){if(running)return;simulation=createSimulation(plan);report=null;policy='balanced';tick=0;running=!simulation.done;tab='simulate';if(simulation.done)report=missionReport(simulation,approvals);render();root.querySelector('.mc-scroll').scrollTop=0;}
function bind(){const all=(selector,fn)=>root.querySelectorAll(selector).forEach(fn);all('[data-tab]',b=>b.onclick=()=>{if(running){flash('Pause the simulation before changing panels.');return;}tab=b.dataset.tab;inspect=false;api.inspectDesign?.(false);render();root.querySelector('.mc-scroll').scrollTop=0;});all('[data-field]',el=>el.onchange=()=>change(el.dataset.field,el.value));all('[data-scenario]',b=>b.onclick=()=>change('scenario',b.dataset.scenario));all('[data-participant]',b=>b.onclick=()=>{activeRole=Number(b.dataset.participant);render();});all('[data-instrument]',el=>el.onchange=()=>{const ids=new Set(plan.payload);if(el.checked)ids.add(el.dataset.instrument);else ids.delete(el.dataset.instrument);change('payload',[...ids]);});all('[data-policy]',b=>b.onclick=()=>{policy=b.dataset.policy;render();});all('[data-load]',b=>b.onclick=()=>{const item=saved.find(s=>s.id===Number(b.dataset.load));if(!item)return;plan=sanitizePlan(item.plan);approvals=[false,false,false,false];revision++;activeRole=0;tab='design';simulation=null;report=null;api.previewDesign?.(plan);storeDraft();notice='Saved design loaded. Reviews reset for the new revision.';render();});all('[data-remove]',b=>b.onclick=()=>{saved=saved.filter(s=>s.id!==Number(b.dataset.remove));try{localStorage.setItem(STORE,JSON.stringify(saved));}catch{}render();});const on=(id,fn)=>{const el=root.querySelector('#'+id);if(el)el.onclick=fn;};on('mc-close',close);on('mc-flight',startExpedition);on('mc-run',beginSimulation);all('[data-start-simulation]',b=>b.onclick=beginSimulation);on('mc-play',()=>{running=!running;tick=0;render();});on('mc-step',()=>{running=false;step();render();});on('mc-show-report',()=>{report=missionReport(simulation,approvals);tab='report';render();root.querySelector('.mc-scroll').scrollTop=0;});on('mc-save',saveDesign);on('mc-share',share);on('mc-export-design',()=>download({version:1,plan},'t-minus-design.json'));on('mc-export-report',()=>download(report,'t-minus-mission-report.json'));on('mc-approve',()=>{approvals[activeRole]=true;activity.unshift(TEAM_ROLES[activeRole].name+' reviewed revision '+revision+'.');notice=TEAM_ROLES[activeRole].name+' approved the design.';render();});on('mc-inspect',()=>{inspect=true;api.inspectDesign?.(true);render();});on('mc-end-inspect',()=>{inspect=false;api.inspectDesign?.(false);render();});on('mc-tutorial',()=>{const el=document.createElement('div');el.className='mc-learning';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-label','How the model works');el.innerHTML=`<div class="mc-panel"><button class="mc-learning-close" aria-label="Close learning guide">×</button><div class="mc-kicker">QUICK FLIGHT SCHOOL</div><h2>Six things that shape a mission.</h2><dl><dt>Mass & launch</dt><dd>All hardware and propellant add mass. A launcher carries less to a high-energy destination than to a nearby orbit.</dd><dt>Power & eclipses</dt><dd>Panels generate power only in sunlight. Average supply must cover demand, and a battery must bridge the dark part of an orbit.</dd><dt>Science & instruments</dt><dd>The best payload answers the chosen question. Instruments earn different science value for each objective.</dd><dt>Data & communications</dt><dd>Observations fill onboard storage. Antenna speed, contact time and distance determine how much can be sent. Science counts when Earth receives it.</dd><dt>Budget & lifetime</dt><dd>A longer mission can collect more science, but uses propellant and exposes the spacecraft to more disruptions.</dd><dt>Collaboration</dt><dd>In shared-device team mode, participants own different settings. Each reviews the same design revision; any change resets the reviews.</dd></dl><p>This is a simplified teaching model. It uses daily-average energy and downlink budgets, estimated eclipse needs, coverage factors and scripted seeded disruptions. It does not calculate real trajectories or certify spacecraft.</p></div>`;root.append(el);el.querySelector('button').onclick=()=>el.remove();});const sp=root.querySelector('#mc-speed');if(sp)sp.onchange=()=>speed=Number(sp.value);const input=root.querySelector('#mc-import');if(input)input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>64000){flash('Design file is too large. Choose a T-MINUS design JSON below 64 KB.');return;}try{const imported=JSON.parse(await file.text());const candidate=imported.plan??imported;if(!candidate||typeof candidate!=='object'||Array.isArray(candidate)||!SCENARIOS.some(s=>s.id===candidate.scenario))throw Error('Invalid design');plan=sanitizePlan(candidate);approvals=[false,false,false,false];activeRole=0;simulation=null;report=null;revision++;tab='design';api.previewDesign?.(plan);storeDraft();notice='Design imported. Check all resources and review the new revision.';render();}catch{flash('Could not import this file. Use an exported T-MINUS design or report JSON.');}};}
function step(){if(!simulation||simulation.done)return;stepSimulation(simulation,policy);if(simulation.done){running=false;report=missionReport(simulation,approvals);render();}else updateLive();}
function updateLive(){const s=simulation;if(!s)return;const day=root.querySelector('#mc-sim-day');if(day)day.textContent=s.day;const bar=root.querySelector('#mc-sim-progress');if(bar)bar.style.width=s.day/plan.days*100+'%';const stats=root.querySelector('#mc-live-grid');if(stats)stats.innerHTML=liveStats(s);const feed=root.querySelector('#mc-event-feed');if(feed)feed.innerHTML=eventFeed(s);drawHistory();}
function drawHistory(){const canvas=root.querySelector('#mc-history');if(!canvas||!simulation)return;const ctx=canvas.getContext('2d');if(!ctx)return;const w=900,h=230,left=16,right=884,top=20,bottom=210;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#c1afd31c';ctx.lineWidth=1;for(let i=0;i<5;i++){const y=top+(bottom-top)*i/4;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();}const e=simulation.evaluation;const lines=[{color:'#d5f591',get:r=>r.science/e.target},{color:'#b7a0f3',get:r=>r.buffer/e.bus.storage},{color:'#edbd81',get:r=>r.energy/e.battery.capacity}];for(const line of lines){ctx.beginPath();ctx.strokeStyle=line.color;ctx.lineWidth=2;ctx.moveTo(left,bottom-(line===lines[2]?bottom-top:0));for(const row of simulation.history){const x=left+row.day/plan.days*(right-left),y=bottom-Math.min(1,line.get(row))*(bottom-top);ctx.lineTo(x,y);}ctx.stroke();}ctx.setLineDash([4,5]);ctx.strokeStyle='#d5f59166';ctx.beginPath();ctx.moveTo(left,top);ctx.lineTo(right,top);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#a99bb8';ctx.font='11px sans-serif';ctx.fillText('100% of target / capacity',left,12);}
let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min(.25,Math.max(0,(now-last)/1000));last=now;if(opened&&running&&!document.hidden){tick+=dt*speed;if(tick>=1){tick-=1;step();}}}requestAnimationFrame(animate);
const button=document.createElement('button');button.id='open-mission-control';button.className='mission-control-button';button.textContent='MISSION CONTROL';button.title='Design, simulate and compare missions';button.onclick=open;document.querySelector('.header-actions').prepend(button);const debriefButton=document.createElement('button');debriefButton.className='mc-button';debriefButton.textContent='REVISE MISSION IN MISSION CONTROL';debriefButton.style.marginTop='12px';debriefButton.style.width='100%';debriefButton.onclick=open;document.querySelector('#replay').after(debriefButton);
root.addEventListener('keydown',event=>{if(event.key==='Escape'){event.stopPropagation();if(inspect){inspect=false;api.inspectDesign?.(false);render();}else close();}if(event.key==='Tab'){const nodes=[...root.querySelectorAll('button:not([disabled]),select:not([disabled]),input:not([disabled]):not([hidden]),a[href]')].filter(n=>!n.closest('[hidden]'));if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
addEventListener('keydown',event=>{if(!opened||event.key!=='Escape'||root.contains(event.target))return;if(inspect){inspect=false;api.inspectDesign?.(false);render();}else close();});
api.missionControl={open,close,get plan(){return plan;},get simulation(){return simulation;},get report(){return report;},get approvals(){return approvals;},get revision(){return revision;}};if(settings.autoOpen!==false)open();return api.missionControl;}
